const version='mow-crew-shell-v2',assets=['./index.html','./route.html','./jobs.html','./job.html','./messages.html','./more.html','./crew.css','./crew.js','./mm-client.js','./brand-icon.png','./icon-192.png','./icon-512.png','./sample-yard.jpg','./neighborhood-map.jpg','./manifest.webmanifest'];self.addEventListener('install',e=>{e.waitUntil(caches.open(version).then(async c=>{await Promise.allSettled(assets.map(async u=>{const r=await fetch(u);if(r.ok&&!r.redirected)await c.put(u,r)}));self.skipWaiting()}))});self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(k=>Promise.all(k.filter(x=>x!==version).map(x=>caches.delete(x)))).then(()=>self.clients.claim()))});self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==location.origin)return;const asset=u.pathname===new URL('./',self.registration.scope).pathname?'./index.html':assets.find(a=>u.pathname===new URL(a,self.registration.scope).pathname);if(!asset)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok&&!r.redirected){const copy=r.clone();caches.open(version).then(c=>c.put(asset,copy))}return r}).catch(()=>caches.match(asset)))});
